/* clang-format on */

static void msgdb_get_magnetic_operation(int rot[3][3], double trans[3],
                                         int *timerev, int const op_number) {
    int enc;
    enc = magnetic_symmetry_operations[op_number];

    /* timerev=1 for anti operation, timerev=0 for ordinary operation */
    /* 34012224 = 3^9 * 12^3 */
    *timerev = enc / 34012224;
    spgdb_decode_symmetry(rot, trans, enc % 34012224);
}

static void msgdb_get_operation_index(int indices[2], int const uni_number,
                                      int const hall_number_offset) {
    /* hall_number_offset: offset from the first Hall number to a given one */
    indices[0] =
        magnetic_spacegroup_operation_index[uni_number][hall_number_offset][0];
    indices[1] =
        magnetic_spacegroup_operation_index[uni_number][hall_number_offset][1];
}

MagneticSymmetry *msgdb_get_spacegroup_operations(int const uni_number,
                                                  int const hall_number) {
    int hall_number_offset;
    int operation_index[2];
    MagneticSymmetry *symmetry;

    int i;
    int rot[3][3];
    double trans[3];
    int timerev;

    hall_number_offset = get_hall_number_offset(uni_number, hall_number);
    if (hall_number_offset == -1) {
        return NULL;
    }

    msgdb_get_operation_index(operation_index, uni_number, hall_number_offset);
    debug_print(
        "Load operations with UNI=%d, hall=%d: hall_number_offset=%d order=%d "
        "starts=%d\n",
        uni_number, hall_number, hall_number_offset, operation_index[0],
        operation_index[1]);

    if ((symmetry = sym_alloc_magnetic_symmetry(operation_index[0])) == NULL) {
        return NULL;
    }

    for (i = 0; i < operation_index[0]; i++) {
        msgdb_get_magnetic_operation(rot, trans, &timerev,
                                     operation_index[1] + i);
        mat_copy_matrix_i3(symmetry->rot[i], rot);
        mat_copy_vector_d3(symmetry->trans[i], trans);
        symmetry->timerev[i] = timerev;
    }

    return symmetry;
}

